insert into flashcards (question_id, cloze_text, extra) values
('2014-1','{{c1::Attunement}} is the caregiver''s cross-modal sharing of a child''s emotional state and rhythm, conveying that the inner feeling is understood.',''),
('2014-10','Asking a patient to interpret a proverb like ''Don''t cry over spilled milk'' tests {{c1::abstract thinking}}.',''),
('2014-100','The tricyclic {{c1::amitriptyline}} is widely and effectively used for chronic and neuropathic pain syndromes.',''),
('2014-101','Hippocampal {{c1::tau}}-positive neurofibrillary tangles are the hallmark pathology of {{c2::Alzheimer disease}}.',''),
('2014-102','A preschooler abruptly quitting frightening pretend play most likely did so because the play produced {{c1::excessive anxiety}}.',''),
('2014-103','Visual hallucinations with severe {{c1::neuroleptic sensitivity}} (worsening rigidity and confusion on antipsychotics) points to {{c2::dementia with Lewy bodies}}.',''),
('2014-104','The potassium-sparing diuretic {{c1::amiloride}} treats lithium-induced polyuria/nephrogenic diabetes insipidus while having the least effect on lithium levels.',''),
('2014-105','{{c1::Native Americans}} have the highest suicide rate of any U.S. racial or ethnic group.',''),
('2014-106','In a sociocultural assessment, the priority is to {{c1::learn the patient and family''s own explanatory model}} of the illness and its expected course.',''),
('2014-107','Therapeutic empathy is the ability to {{c1::grasp the patient''s inner experience from the patient''s own perspective}}, distinct from sympathy.',''),
('2014-108','Current evidence shows {{c1::no significant association between beta-blockers and depression}}.',''),
('2014-109','{{c1::Following commands during an event}} (preserved responsiveness) suggests a psychogenic nonepileptic seizure rather than a true generalized seizure.',''),
('2014-11','The natural course of an untreated manic episode lasts approximately {{c1::3 months}}.',''),
('2014-110','The hallmark of amphetamine-induced psychosis is {{c1::paranoia}}.',''),
('2014-111','For a depressed patient bothered by SSRI-related sexual and GI side effects, {{c1::bupropion}} is a good first-line choice that avoids those effects.',''),
('2014-112','An {{c1::EEG}} showing diffuse slowing helps distinguish {{c2::delirium}} from dementia.',''),
('2014-113','An insightful, psychologically-minded patient with a focal conflict and limited sessions is best suited to {{c1::brief psychodynamic therapy}}.',''),
('2014-114','Café-au-lait macules, cutaneous neurofibromas, and axillary freckling are diagnostic of {{c1::neurofibromatosis type 1}}.',''),
('2014-115','{{c1::Motivational enhancement therapy}} targets patient ambivalence as its central treatment focus in alcoholism.',''),
('2014-116','Per APA ethics, a psychiatrist should {{c1::avoid romantic relationships with any third party (family member) of a patient}}.',''),
('2014-117','Beyond supportive care, neuroleptic malignant syndrome may be treated with {{c1::dopamine agonists}} such as bromocriptine (and dantrolene).',''),
('2014-118','Anthropologically, dissociative experiences most commonly represent {{c1::normal components of religious and ritual practices}} worldwide.',''),
('2014-119','{{c1::Huntington disease}} is caused by a {{c2::CAG trinucleotide repeat expansion}} in the HTT gene.',''),
('2014-12','On EEG, {{c1::triphasic waves}} and generalized slowing are most consistent with {{c2::metabolic encephalopathy}}.',''),
('2014-120','The principal goal of wraparound services for youth is to {{c1::prevent hospitalization or residential placement}} by supporting them in the community.',''),
('2014-121','Well-formed, complex visual hallucinations with preserved insight in a person with severe vision loss define {{c1::Charles Bonnet syndrome}}.',''),
('2014-122','In Minuchin''s structural family therapy, overly diffuse boundaries where members are overinvolved (e.g., a parent saying "our disease") describe an {{c1::enmeshed}} family.',''),
('2014-123','SSRI-induced hyponatremia from {{c1::SIADH}} is confirmed by an inappropriately concentrated {{c2::urine osmolality}} despite low serum sodium.',''),
('2014-124','{{c1::Parallel play}}, typical of {{c2::2-year-olds}}, is playing alongside but not with another child.',''),
('2014-125','{{c1::Borderline}} personality disorder may feature transient, stress-related psychotic or dissociative symptoms.',''),
('2014-126','The immediate goal in acute disaster crisis intervention is to provide a {{c1::structured approach to build self-efficacy}}, not pharmacologic prophylaxis.',''),
('2014-127','{{c1::Topiramate}} is a first-line agent for migraine {{c2::prophylaxis}}, whereas sumatriptan and naproxen are for acute attacks.',''),
('2014-128','Recognizing that quantity stays the same despite a change in shape demonstrates {{c1::conservation}}, a Piagetian concrete-operational milestone.',''),
('2014-129','The recommended treatment for opioid dependence in pregnancy is {{c1::methadone maintenance}}, not detoxification or taper.',''),
('2014-13','The initial pharmacologic treatment for childhood ADHD is a {{c1::stimulant}} such as {{c2::methylphenidate}}.',''),
('2014-130','The triad of dementia, urinary incontinence, and gait disturbance is normal pressure hydrocephalus, with MRI showing {{c1::ventricular dilatation}}.',''),
('2014-131','Decision-making capacity requires that a patient {{c1::appreciate the consequences}} of refusing treatment; a normal MMSE alone does not establish capacity.',''),
('2014-132','Effective patient handoffs should include a {{c1::summary of the treatment course and a risk assessment}}.',''),
('2014-133','{{c1::Anticholinergic}} drugs like oxybutynin counteract the cholinesterase inhibitor {{c2::donepezil}}, reducing its efficacy in dementia.',''),
('2014-134','By about age 4, language skills are sufficient for {{c1::storytelling using words}}.',''),
('2014-135','The final phase of Mahler''s separation-individuation is {{c1::object constancy}}, maintaining a positive attachment despite frustration.',''),
('2014-136','Intermittent explosive disorder and impulsive aggression are associated with {{c1::decreased CSF serotonin}} (low 5-HIAA).',''),
('2014-137','When a patient is incompetent, treatment must be approved by the legally designated surrogate, the {{c1::assigned decision maker}} (durable power of attorney for healthcare).',''),
('2014-138','{{c1::Atomoxetine}}, a non-stimulant, is preferred for ADHD in patients with a {{c2::substance use disorder}} because it lacks abuse potential.',''),
('2014-139','When a therapist''s attention drifts during a session, the best response is to examine one''s own {{c1::countertransference}} (inner thoughts and feelings about the patient).',''),
('2014-14','Overriding a parent''s refusal to remove firearms by reporting to CPS conflicts most directly with the ethical principle of {{c1::autonomy}}.',''),
('2014-140','Transient postictal deficits such as {{c1::Todd paralysis}} or aphasia help {{c2::localize the seizure focus}}.',''),
('2014-141','Full penile erection and emission of pre-ejaculatory seminal fluid occur during the {{c1::excitement and plateau}} phases of the sexual response cycle.',''),
('2014-142','Because the prefrontal cortex lacks dopamine transporters, synaptic dopamine there is terminated mainly by {{c1::diffusion away from the synaptic cleft}}.',''),
('2014-143','Acute alcohol intoxication is mediated by {{c1::NMDA receptor antagonism}} and {{c2::GABA receptor agonism}}.',''),
('2014-144','Vertigo with ipsilateral facial sensory loss, ataxia, hoarseness, and contralateral body sensory loss is {{c1::lateral medullary (Wallenberg) syndrome}} from PICA-territory stroke.',''),
('2014-145','Genetic {{c1::anticipation}} is earlier onset or greater severity of disease in each succeeding generation, due to {{c2::trinucleotide repeat expansion}}.',''),
('2014-146','Conduction block on nerve conduction studies indicates {{c1::focal demyelination}} rather than axonal loss.',''),
('2014-147','A {{c1::Type I error}} (false positive) is concluding a treatment is effective when it actually is not.',''),
('2014-148','Valproic acid raises lamotrigine levels and dermatologic risk by {{c1::inhibiting glucuronidation}} of lamotrigine, requiring slower lamotrigine titration.',''),
('2014-149','Cervical myelopathy from age-related disc and joint degeneration with cord compression on MRI is {{c1::degenerative cervical spondylosis}}.',''),
('2014-15','Sudden loss of voice after an emotional argument, with a normal exam and preserved cough, indicates {{c1::conversion disorder}} (functional neurological symptom disorder).',''),
('2014-150','Cervical dystonia (spasmodic torticollis), often relieved by a sensory geste antagoniste, is best treated with {{c1::botulinum toxin}} injection.',''),
('2014-151','Beyond nicotine replacement, {{c1::varenicline}} has the strongest evidence for smoking cessation.',''),
('2014-152','The most feared complication of temporal arteritis is irreversible blindness from occlusion of the {{c1::ophthalmic artery}}.',''),
('2014-153','A forensic psychiatrist taking a {{c1::contingency fee (percentage of the award)}} is unethical because it compromises objectivity.',''),
('2014-154','Under {{c1::OBRA-1987}}, antipsychotics in nursing-home residents require periodic attempts to {{c2::reduce or discontinue}} the dose (gradual dose reduction).',''),
('2014-155','The primary goal of {{c1::supportive psychotherapy}} is to stabilize functioning and strengthen the patient''s existing {{c2::defenses}}.',''),
('2014-156','{{c1::Carbamazepine}}, a CYP3A4 inducer, lowers methadone levels and can precipitate opioid withdrawal.',''),
('2014-157','Family psychoeducation reduces psychotic relapse largely by lowering high {{c1::expressed emotion}} (criticism, hostility, overinvolvement).',''),
('2014-158','Depigmentation (loss of neuromelanin) of the {{c1::substantia nigra}} on gross midbrain section is characteristic of {{c2::Parkinson disease}}.',''),
('2014-159','Orally ingested amphetamines reach peak plasma levels at about {{c1::2 hours}}.',''),
('2014-16','Sleep terrors arise from {{c1::non-REM (slow-wave)}} sleep and characteristically have their {{c2::onset in childhood}}.',''),
('2014-160','Besides orientation, attention, calculation, language, and registration, the {{c1::MMSE}} also tests {{c2::recall}}.',''),
('2014-161','In a pure {{c1::liaison}} model of consultation, the psychiatrist educates the team (e.g., advising how to evaluate depression) rather than directly seeing the patient.',''),
('2014-162','Fixed nonbizarre delusions (e.g., infidelity) with otherwise normal function and no other psychosis indicate {{c1::delusional disorder}}.',''),
('2014-163','Abrupt arousals with terror and autonomic surge during non-REM sleep, with no recall the next morning, define {{c1::sleep terrors}}.',''),
('2014-164','Neonatal hyperexcitability (tremor, irritability) followed by depressed responsiveness suggests prenatal {{c1::cocaine}} exposure.',''),
('2014-165','{{c1::REM sleep behavior disorder}} (dream enactment with movement) strongly predicts later {{c2::Parkinson disease}} and other synucleinopathies.',''),
('2014-166','{{c1::Lamotrigine}} is most effective for {{c2::bipolar depression}} and maintenance, but not for acute mania.',''),
('2014-167','Smoking induces CYP1A2 and lowers levels of {{c1::olanzapine}} (and clozapine), often requiring higher doses.',''),
('2014-168','The first-line psychotherapeutic approach for childhood ADHD with ODD is {{c1::parent-managed behavioral therapy}} with a rewards program.',''),
('2014-169','A sociobiologist views PTSD {{c1::hypervigilance}} as adaptive for rapidly detecting real threats.',''),
('2014-17','Controlled trials support {{c1::atypical antipsychotics}} as an effective augmentation of SSRIs for treatment-resistant PTSD.',''),
('2014-170','Interpersonal and social rhythm therapy for bipolar disorder targets {{c1::lifestyle/social rhythm regularity}} to stabilize circadian routines.',''),
('2014-171','Normal pressure hydrocephalus, confirmed by gait improvement after CSF removal, shows {{c1::enlarged ventricles/frontal horns}} out of proportion to atrophy.',''),
('2014-172','A toddler''s language develops most through the parent {{c1::engaging in frequent conversation and thinking aloud}}.',''),
('2014-173','Euphoria with visual disturbance and hallucinations soon after a body-builder''s liquid "supplement" suggests {{c1::GHB}} ingestion.',''),
('2014-174','In a fitness-for-duty evaluation, the administrative psychiatrist serves the organization and is {{c1::not bound by usual confidentiality}}, which must be disclosed up front.',''),
('2014-175','When anticholinergics like benztropine cause urinary retention and confusion, {{c1::amantadine}} is a better agent for antipsychotic-induced parkinsonism.',''),
('2014-176','The {{c1::Stroop Color-Word Test}} assesses executive function by requiring inhibition of the overlearned response of reading.',''),
('2014-177','The leading preventable biological cause of intellectual disability is prenatal {{c1::alcohol}} exposure (fetal alcohol syndrome).',''),
('2014-178','When using an interpreter, the clinician should look at and address the {{c1::patient directly using "you"}}, and avoid using family members as interpreters.',''),
('2014-179','{{c1::Sertraline}} is the preferred first-line SSRI for postpartum depression in {{c2::breastfeeding}} mothers due to low infant exposure.',''),
('2014-18','If trauma-related symptoms persist longer than {{c1::4 weeks}}, the diagnosis shifts from acute stress disorder to {{c2::PTSD}}.',''),
('2014-180','The most effective abortive treatment for an acute migraine is a triptan such as {{c1::sumatriptan}}.',''),
('2014-181','Peek-a-boo delights infants because it tests {{c1::object permanence}}, the understanding that objects continue to exist when out of sight.',''),
('2014-182','Self-induced vomiting in {{c1::bulimia nervosa}} causes a hypokalemic, hypochloremic {{c2::metabolic alkalosis}} with elevated amylase from the salivary glands.',''),
('2014-183','{{c1::Memantine}} treats Alzheimer dementia by acting as a partial antagonist (blocker) of the {{c2::NMDA}} receptor, unlike the cholinesterase inhibitors.',''),
('2014-184','{{c1::MDMA (ecstasy)}} characteristically causes bruxism, anorexia, diaphoresis, impaired orgasm, and hot flashes via serotonin release.',''),
('2014-185','The most effective measure to prevent adolescent suicide is {{c1::reducing access to firearms}} in the home (means restriction).',''),
('2014-186','In nonsuicidal self-injury, comorbid {{c1::alcohol (substance) abuse}} most strongly supports inpatient admission because intoxication raises the risk of impulsive lethal acts.',''),
('2014-187','Bilateral lesions of the {{c1::mammillary bodies}} produce the Korsakoff triad of amnesia, {{c2::confabulation}}, and lack of insight.',''),
('2014-188','Psychosis with abdominal pain and proximal motor neuropathy suggests acute intermittent porphyria, confirmed by elevated urine {{c1::porphobilinogen}}.',''),
('2014-189','{{c1::Cimetidine}} inhibits hepatic CYP enzymes, raising methadone levels and causing increased sedation, unlike other H2 blockers or PPIs.',''),
('2014-19','The most common reason adults over 65 report difficulty maintaining sleep is {{c1::nocturia}}.',''),
('2014-190','First-line pharmacotherapy for OCD is an {{c1::SSRI}} such as {{c2::escitalopram}}, often at higher doses than used for depression.',''),
('2014-191','Obesity, snoring, and enlarged tonsils suggest {{c1::obstructive sleep apnea}}, whose correction can improve ADHD-like symptoms of inattention and hyperactivity.',''),
('2014-192','Practicing to remove an aversive stimulus (parental nagging) is {{c1::negative reinforcement}}, which increases the behavior by taking something away.',''),
('2014-193','Experimenting with self-disclosure and conflict marks the {{c1::storming}} stage of group development.',''),
('2014-194','Myasthenia gravis is diagnosed by detecting antibodies against the {{c1::acetylcholine receptor}} at the neuromuscular junction.',''),
('2014-195','Loss of autobiographical memory for family/personal events with intact general cognition after trauma indicates {{c1::dissociative amnesia}}, not an organic lesion.',''),
('2014-196','{{c1::Prazosin}}, an alpha-1 antagonist, has the best controlled-trial evidence for reducing {{c2::nightmares}} in PTSD.',''),
('2014-197','Tinnitus, nausea/vomiting, and hyperventilation (respiratory alkalosis) point to {{c1::aspirin (salicylate)}} overdose.',''),
('2014-198','A core goal of psychoeducation after a first schizophrenia hospitalization is emphasizing {{c1::medication adherence}} to prevent relapse.',''),
('2014-199','{{c1::Lung}} cancer is the malignancy that most commonly metastasizes to the brain.',''),
('2014-2','{{c1::Twelve-step facilitation}} uses a {{c2::disease-model}} approach to addiction, emphasizing acceptance of the disease and surrender to help beyond oneself.',''),
('2014-20','The most specific test of executive functioning is the {{c1::Wisconsin Card Sorting Test}}.',''),
('2014-200','Transient emotional reactivity and regression after starting kindergarten is best explained as a {{c1::normative stress response}} to the school transition.',''),
('2014-201','A hallmark of the {{c1::melancholic}} subtype of depression is {{c2::anhedonia}} (loss of pleasure in all activities), unlike the mood reactivity of atypical depression.',''),
('2014-202','{{c1::Naltrexone}} is a pure {{c2::opioid antagonist}} used for alcohol and opioid use disorders.',''),
('2014-203','Antidepressants can induce rapid cycling in bipolar disorder, so the best step for an antidepressant-associated cycling is to {{c1::discontinue the antidepressant (paroxetine)}}.',''),
('2014-204','Stopping antipsychotics because "nothing is wrong anymore" reflects {{c1::poor insight}}, a failure to recognize one''s own illness.',''),
('2014-205','Dopamine agonist therapy for {{c1::Parkinson disease}} is associated with treatment-emergent {{c2::impulse control disorders}} such as pathologic gambling.',''),
('2014-206','Taijin kyofusho (fear of offending others, e.g., with body odor) is the culture-bound condition most analogous to {{c1::social phobia}}.',''),
('2014-207','Excessive daytime sleep attacks are caused by narcolepsy, which shows decreased CSF {{c1::hypocretin (orexin)}}.',''),
('2014-208','{{c1::Mimicking intercourse}} during play is an atypical sexual behavior in a preschooler that may warrant concern for abuse.',''),
('2014-209','{{c1::Down syndrome (trisomy 21)}} is the most common genetic cause of intellectual disability overall, while Fragile X is the most common inherited cause.',''),
('2014-21','In classical conditioning, repeated exposure to the conditioned stimulus {{c1::without the unconditioned stimulus}} produces {{c2::extinction}} of the conditioned response.',''),
('2014-210','Among SSRIs, {{c1::fluvoxamine}} is the most potent inhibitor of hepatic CYP enzymes and thus most likely to cause drug interactions.',''),
('2014-211','{{c1::Carbohydrate-deficient transferrin (CDT)}} is the most sensitive lab marker for sustained heavy daily alcohol consumption.',''),
('2014-212','When a patient has delusional parasitosis, the clinician should first {{c1::screen for substance use}}, since stimulants and alcohol can produce formication.',''),
('2014-213','The evidence-based behavioral treatment for tic disorders is {{c1::habit reversal therapy}} (a component of CBIT).',''),
('2014-214','Catatonia (mutism, posturing, waxy flexibility) is treated first-line with a {{c1::benzodiazepine (lorazepam)}} challenge.',''),
('2014-215','A clinician uses {{c1::reflective statements}} primarily to confirm that the patient''s meaning was {{c2::accurately understood}}.',''),
('2014-216','Recurrent episodes of hypersomnia with hyperphagia and cognitive/behavioral changes in an adolescent suggest {{c1::Kleine-Levin syndrome}}.',''),
('2014-217','A {{c1::double bind}} delivers contradictory messages at once, such as encouraging college while framing it as a hardship on the family.',''),
('2014-218','{{c1::Clozapine}} is the antipsychotic proven to reduce suicide rates in patients with schizophrenia.',''),
('2014-219','When dementia impairs driving, the physician must {{c1::consult state law}} regarding mandatory reporting obligations.',''),
('2014-22','Common to all couple and family therapies is {{c1::conceptualizing difficulties in relational terms}} rather than as individual pathology.',''),
('2014-220','The most common comorbidity with a childhood reading disability is {{c1::ADHD (inattentive type)}}.',''),
('2014-221','Becoming less fearful of biking after watching peers enjoy it illustrates {{c1::modeling}} (observational learning).',''),
('2014-222','Interpersonal psychotherapy (IPT) targets the {{c1::here-and-now interpersonal problem}}, working to increase social contacts and strengthen existing relationships.',''),
('2014-223','Impaired clock drawing with neglect/visuospatial errors localizes to the {{c1::parietal lobe}} (often nondominant).',''),
('2014-224','For narcolepsy (REM onset within minutes) the preferred wake-promoting agent is {{c1::modafinil}}, favored over stimulants in patients with addiction history.',''),
('2014-225','Civil medical malpractice must be proven by a {{c1::preponderance of the evidence}}, a lower standard than "beyond a reasonable doubt."',''),
('2014-226','Trazodone needs much higher doses for antidepressant effect because it has low potency at the {{c1::serotonin transporter}}, while its hypnotic effects come from H1/5-HT2 blockade at low doses.',''),
('2014-227','{{c1::Thiazide diuretics}} reduce renal lithium clearance, precipitating {{c2::lithium toxicity}} (tremor, dysarthria, confusion).',''),
('2014-228','The most important side effect to discuss before ECT, especially in the elderly, is {{c1::cognitive dysfunction (memory impairment)}}.',''),
('2014-229','Hopelessness in a terminally ill patient without a death plan is often a {{c1::normal reaction}} that should be {{c2::validated}} rather than pathologized.',''),
('2014-23','The most useful instrument to assess a nonverbal, socially aloof child for autism is the {{c1::Autism Diagnostic Observation Schedule (ADOS)}}.',''),
('2014-230','Confusion, ataxia, and ophthalmoplegia after giving glucose to a malnourished alcoholic is Wernicke encephalopathy, treated with {{c1::thiamine}} (given before glucose).',''),
('2014-231','Structural family therapy considers healthy a {{c1::clear boundary}} between the parental and child subsystems that preserves authority while allowing communication.',''),
('2014-232','{{c1::Directed masturbation}} (sometimes with a vibrator) is the behavioral treatment for {{c2::female orgasmic disorder}}.',''),
('2014-233','Nonfluent, effortful Broca aphasia results from lesions of the {{c1::inferior frontal gyrus}} of the dominant hemisphere.',''),
('2014-234','Psychoeducation for an overburdened caregiver should encourage maintaining {{c1::their own self-care and support networks (e.g., church group)}} to prevent burnout.',''),
('2014-235','Plasma-level monitoring correlates best with clinical response for {{c1::clozapine}} and {{c2::haloperidol}}.',''),
('2014-236','A lifetime history of {{c1::three or more depressive episodes}} indicates the need for long-term maintenance antidepressant therapy.',''),
('2014-237','Channeling jealousy into dedicated martial arts training is {{c1::sublimation}}, redirecting an unacceptable impulse into a socially valued activity.',''),
('2014-238','Speech linked by rhyme and sound rather than meaning is {{c1::clang associations}}.',''),
('2014-239','{{c1::Interferon}} therapy is the immunomodulator most associated with inducing significant depression in cancer patients.',''),
('2014-24','Dissociative amnesia involves an inability to retrieve {{c1::episodic (autobiographical)}} memory, typically of stressful or traumatic events.',''),
('2014-240','{{c1::Testosterone}} is the most effective treatment for hypoactive sexual desire in postmenopausal women.',''),
('2014-241','{{c1::Valproate}} significantly raises serum lamotrigine levels by inhibiting its glucuronidation, so lamotrigine must be {{c2::dose-reduced}} when combined with it.',''),
('2014-242','Acute ascending areflexic weakness with nerve conduction showing slow velocity, prolonged distal latency, and conduction block indicates {{c1::acute inflammatory demyelinating polyneuropathy (Guillain-Barre)}}.',''),
('2014-243','Hallucinations in conversion disorder typically have a {{c1::childish, fantastic quality}} rather than the qualities seen in true psychotic illness.',''),
('2014-244','Severe lithium toxicity can cause permanent neurologic damage to the {{c1::cerebellum}}, leading to persistent ataxia and dysarthria.',''),
('2014-245','In an elderly demented patient with acute agitation and worsening confusion, the first step is to evaluate for delirium, most commonly from a {{c1::urinary tract infection}}, via {{c2::urinalysis}}.',''),
('2014-246','At very high blood alcohol concentrations (e.g., >0.4 g/dL), the most immediate life-threatening concern is {{c1::respiratory failure}} from CNS depression.',''),
('2014-247','When a referring clinician idealizes a patient as ''special,'' the new therapist should anticipate {{c1::splitting}} between the two treaters.',''),
('2014-248','Contralateral leg weakness sparing the face and arm, plus urinary incontinence and abulia, localizes to an {{c1::anterior cerebral artery}} stroke.',''),
('2014-249','Factitious disorder is distinguished from malingering by the motivation: assuming the {{c1::sick role}} itself, rather than obtaining external {{c2::secondary gain}}.',''),
('2014-25','Among APA malpractice claims, the most common allegation of harm is {{c1::incorrect treatment}}.',''),
('2014-250','When a parent abruptly leaves a distressed infant without comforting them, the child tends to develop increased {{c1::clinging and avoidant}} behavior toward the parents.',''),
('2014-251','A threat to damage property (rather than serious bodily harm to an identifiable person) does not trigger a duty to protect, so the psychiatrist has {{c1::no legal obligation}} to warn or report.',''),
('2014-252','The most serious adverse effect of repetitive transcranial magnetic stimulation (rTMS) is {{c1::seizure}}.',''),
('2014-253','For a young child with morning reluctance, somatic complaints, and emotional outbursts suggesting school refusal, the next step is to obtain a release to {{c1::speak with the teacher}} for collateral information.',''),
('2014-254','The triad of ophthalmoplegia/nystagmus, ataxia, and confusion in an alcoholic indicates Wernicke encephalopathy from {{c1::thiamine (vitamin B1)}} deficiency.',''),
('2014-255','A child using a toy phone to ''talk to Daddy'' demonstrates {{c1::symbolic representation}}, using one object to stand for something else in pretend play.',''),
('2014-256','Among major anxiety disorders, {{c1::specific phobia}} is the one most likely to have onset in childhood.',''),
('2014-257','The term ''schizophrenia'' was first coined by {{c1::Eugen Bleuler}}, replacing Kraepelin''s earlier term ''dementia praecox.''',''),
('2014-258','Selecting subjects by outcome (babies with vs. without Ebstein''s anomaly) and comparing prior exposure defines a {{c1::case-control}} study.',''),
('2014-259','EEG biofeedback (neurofeedback) has shown superiority over progressive muscle relaxation in the treatment of {{c1::insomnia disorder}}.',''),
('2014-26','The most common reason patients discontinue SSRIs early in treatment is {{c1::gastrointestinal side effects}}.',''),
('2014-260','In a chronic pain patient on opioids, true addiction is best indicated by aberrant behavior such as {{c1::using the drug by a route other than prescribed}}, not by tolerance or physical dependence alone.',''),
('2014-261','When served a subpoena for records, the ethical action is to oppose release on the grounds of {{c1::lack of patient consent}}, since a subpoena alone does not compel disclosure.',''),
('2014-262','{{c1::Folic acid}} supplementation can mask vitamin B12 deficiency by correcting the macrocytic anemia while {{c2::neurologic damage}} progresses.',''),
('2014-263','{{c1::Lithium}} is the mood stabilizer most firmly associated with reduced long-term suicide risk in bipolar disorder.',''),
('2014-264','An absolute contraindication to sildenafil is concurrent use of {{c1::nitrates}} (e.g., nitroglycerin), due to risk of severe {{c2::hypotension}}.',''),
('2014-265','An essential element of the wraparound approach is integrating formal mental health services with {{c1::informal community/natural supports}}.',''),
('2014-266','Internuclear ophthalmoplegia (impaired adduction of one eye with nystagmus of the abducting eye) in a young woman strongly suggests {{c1::multiple sclerosis}}.',''),
('2014-267','Avoidant personality disorder differs from schizoid in that avoidant patients {{c1::desire social relationships}} but avoid them due to fear of rejection.',''),
('2014-268','Recurrent involuntary obscene gestures, as seen in Tourette syndrome, are termed {{c1::copropraxia}}.',''),
('2014-269','Irritability, declining function, and mood-congruent auditory hallucinations in a child are most consistent with {{c1::major depressive disorder}} with psychotic features rather than schizophrenia.',''),
('2014-27','Confusion, hallucinations, autonomic hyperactivity, and tremor with EEG fast waves on slow waves in a heavy drinker indicate {{c1::delirium from alcohol withdrawal}}.',''),
('2014-270','Back pain plus fever with progressive myelopathy (paraparesis, sensory loss, incontinence) in an IV drug user indicates a {{c1::spinal epidural abscess}}.',''),
('2014-271','Withholding a terminal diagnosis from a child tends to {{c1::leave the child alone to cope with worries}}, as children often sense the truth without support.',''),
('2014-272','The most effective treatment for obstructive sleep apnea is {{c1::positive airway pressure (CPAP)}} therapy.',''),
('2014-273','Incompetence to stand trial hinges on inability to {{c1::work with one''s attorney}} or understand the proceedings, e.g., believing all lawyers are demons and refusing to speak to them.',''),
('2014-274','The highest smoking-cessation success comes from combining pharmacotherapy with behavioral support, such as {{c1::bupropion plus group therapy}}.',''),
('2014-275','The initial recommended approach for a child with new-onset tics is {{c1::clinical monitoring (watchful waiting)}}, since most tics are mild and self-limited.',''),
('2014-276','Promoting flu shots to prevent illness before it occurs is an example of {{c1::primary prevention}}.',''),
('2014-277','Hypnotizability is most strongly predicted by an individual''s {{c1::capacity for imaginative involvement (absorption)}}.',''),
('2014-278','Nocturnal hand ''pins and needles'' relieved on waking is most often due to {{c1::carpal tunnel syndrome}} (median nerve compression).',''),
('2014-279','Helping an alcohol-dependent patient change routes home to avoid high-risk cues is a {{c1::cognitive-behavioral}} therapy technique.',''),
('2014-28','For a severely ill, non-adherent patient with repeated hospitalizations and poor family support, the most appropriate modality is {{c1::assertive community treatment}}.',''),
('2014-280','Federal law (42 CFR Part 2) holds {{c1::substance abuse}} treatment records to a stricter confidentiality standard than other psychiatric records.',''),
('2014-281','Recruiting a patient''s spouse as a healthy control during the patient''s visit risks violating {{c1::voluntarism}}, due to potential coercion or undue influence.',''),
('2014-282','On the mental status exam, {{c1::mood}} relies primarily on the patient''s own report, whereas affect is based on clinician observation.',''),
('2014-283','Framing a sensitive behavior as common and understandable to reduce shame and elicit honest disclosure is the interview technique of {{c1::normalization}}.',''),
('2014-284','Childhood absence epilepsy (brief staring with eyelid fluttering) is treated with {{c1::ethosuximide}}, or {{c2::valproic acid}} when convulsive seizures coexist.',''),
('2014-285','Stage N2 sleep is identified on EEG by {{c1::K-complexes and sleep spindles}}.',''),
('2014-286','Frequent falls with axial rigidity, an erect stiff gait, en-bloc turning, and vertical gaze palsy characterize {{c1::progressive supranuclear palsy}}.',''),
('2014-287','For illness anxiety disorder with persistent fear of cardiac disease despite normal testing, the treatment with the best evidence is {{c1::cognitive-behavioral therapy}}.',''),
('2014-288','The statistic that quantifies the magnitude of difference between two groups (independent of sample size) is the {{c1::effect size}}.',''),
('2014-289','Acute dystonia (tongue protrusion, torticollis, dysarthria) on a medical floor should prompt suspicion of the dopamine antagonist {{c1::metoclopramide}}.',''),
('2014-29','Situational erectile dysfunction with normal masturbatory function and a healthy relationship is best managed initially by {{c1::including the partner}} in behavioral sex therapy.',''),
('2014-290','Dementia with myoclonus plus cortical spongiform change (cytosolic vacuolation with prion inclusions) on biopsy indicates {{c1::Creutzfeldt-Jakob disease}}.',''),
('2014-291','Alcohol withdrawal seizures are typically {{c1::generalized}} and occur as {{c2::multiple}} episodes within the first 6-48 hours of cessation.',''),
('2014-292','{{c1::Marginalization}} (rejecting both native and host cultures) is the acculturation outcome linked to the highest risk of suicide, substance abuse, and alcoholism.',''),
('2014-293','A major depressive episode superimposed on pre-existing chronic dysthymia is termed {{c1::double depression}}.',''),
('2014-294','Among insomnia medications, the benzodiazepine {{c1::temazepam}} is most likely to cause {{c2::anterograde amnesia}}/amnestic impairment.',''),
('2014-295','A {{c1::lens-shaped (biconvex)}} hyperdensity that does not cross suture lines on head CT indicates an {{c2::epidural hematoma}}.',''),
('2014-296','Alcohol-induced blackouts are episodes of {{c1::anterograde amnesia}} occurring while the person is awake and drinking heavily.',''),
('2014-297','The perinatal factor specifically associated with ADHD is {{c1::prenatal maternal tobacco/smoking}} exposure.',''),
('2014-298','A psychiatrist should decline a patient''s social-media friend request because it disrupts the {{c1::boundaries of the therapeutic frame}}.',''),
('2014-299','A pure sensory stroke affecting the contralateral face, arm, trunk, and leg is caused by a lacunar infarct of the {{c1::lateral (ventral posterolateral) thalamus}}.',''),
('2014-3','{{c1::Anosognosia}} with denial of left-sided weakness and hemineglect localizes to a lesion of the right {{c2::parietal lobe}}.',''),
('2014-30','Acute vertigo, diplopia, and occipital pain during neck manipulation suggest {{c1::vertebral artery dissection}}.',''),
('2014-300','In Kohlberg''s model, the highest (postconventional) stage of moral reasoning is guided by {{c1::universal ethical principles}}.',''),
('2014-31','Transient same- and opposite-sex experiences during adolescence are best understood as {{c1::normal experimentation in sexual identity}}.',''),
('2014-32','In the CAMS study of pediatric anxiety, {{c1::combination of sertraline plus CBT}} was superior to either monotherapy alone.',''),
('2014-33','{{c1::Disulfiram}} treats alcohol dependence by inhibiting {{c2::aldehyde dehydrogenase}}, causing acetaldehyde accumulation and an aversive reaction.',''),
('2014-34','Lithium responds most favorably during the {{c1::maintenance}} phase and in {{c2::acute mania}} of bipolar disorder, and poorly in rapid cycling.',''),
('2014-35','Manic symptoms emerging within days of starting an antidepressant, with no prior mood history, indicate {{c1::substance/medication-induced bipolar disorder}}.',''),
('2014-36','On an inpatient unit, frequent {{c1::patient turnover}} most impedes the development of group cohesion.',''),
('2014-37','New-onset burning pain with intercourse and reflexive tensing warrants {{c1::referral to a gynecologist}} for a comprehensive exam to exclude organic causes first.',''),
('2014-38','A {{c1::cerebellar}} tremor is ~3 Hz with irregular amplitude and worsens at the {{c2::end of reaching (intention)}} movements.',''),
('2014-39','The ''Little Albert'' fear-conditioning experiment violated {{c1::nonmaleficence}} by deliberately inducing harm in an infant.',''),
('2014-4','Dysprosody is an abnormality of {{c1::speech}}, specifically the rhythm, melody, and intonation that convey emotional tone.',''),
('2014-40','Acute paranoid psychosis with agitation in a young patient most often shows {{c1::amphetamine}} on urine toxicology.',''),
('2014-41','Severe lithium toxicity (level ~4.5 with neurologic and renal compromise) is treated with emergent {{c1::hemodialysis}}.',''),
('2014-42','{{c1::Lithium}} is most associated with prolonged seizures and confusional states during ECT and is usually held beforehand.',''),
('2014-43','{{c1::Lithium}} can exacerbate the skin condition {{c2::psoriasis}}.',''),
('2014-44','Ketamine acts as an {{c1::antagonist at NMDA (N-methyl-D-aspartate) receptors}}.',''),
('2014-45','When a patient admits to intimate-partner violence, the psychiatrist should clearly state that the {{c1::violence is his responsibility and must stop}}.',''),
('2014-46','New irritability and hyperactivity in a child on stimulants is best managed by {{c1::decreasing the stimulant dose}}.',''),
('2014-47','The treatment of choice for treatment-resistant schizophrenia is {{c1::clozapine}}.',''),
('2014-48','A {{c1::cross-sectional}} study design is most appropriate for estimating the {{c2::prevalence}} of a disorder.',''),
('2014-49','Expressing condolences to a deceased patient''s spouse is appropriate when a {{c1::long-term therapeutic relationship}} existed with both.',''),
('2014-5','First-line pharmacotherapy for panic disorder is an {{c1::SSRI}} (e.g., {{c2::fluoxetine}}), not a benzodiazepine.',''),
('2014-50','Fever, seizure, personality change, and {{c1::temporal lobe}} T2 lesions point to {{c2::herpes (HSV) encephalitis}}.',''),
('2014-51','For a child wanting rapid, short-term control of nocturnal enuresis (e.g., for camp), a trial of {{c1::DDAVP (desmopressin)}} is appropriate.',''),
('2014-52','Impaired physicians over 65 most often come to medical boards'' attention through reports from {{c1::other physicians}}.',''),
('2014-53','Psychomotor retardation, slurred speech, drowsiness, and {{c1::pinpoint (miotic) pupils}} indicate {{c2::opioid}} intoxication.',''),
('2014-54','{{c1::Lamotrigine}} is the medication most associated with Stevens-Johnson syndrome, requiring slow titration.',''),
('2014-55','The {{c1::Boston Naming Test}} assesses expressive language (confrontation naming).',''),
('2014-56','{{c1::Glycine}} is a predominantly inhibitory neurotransmitter, acting mainly in the spinal cord and brainstem.',''),
('2014-57','As children move through the school-age period, they begin to {{c1::recognize racial and ethnic stereotypes}}.',''),
('2014-58','An individual needing supervision for self-care, working with support, and with ~2nd-grade academics fits {{c1::moderate}} intellectual disability.',''),
('2014-59','Memory complaints with abnormal delayed recall but preserved independent function and no functional decline indicate {{c1::amnestic mild cognitive impairment}}.',''),
('2014-6','Restlessness, myoclonus, hyperreflexia, diaphoresis, shivering, and tremor characterize {{c1::serotonin syndrome}}.',''),
('2014-60','{{c1::Varenicline}} is a partial nicotinic-receptor agonist that {{c2::blocks the reinforcing effect of nicotine}} while easing withdrawal.',''),
('2014-61','{{c1::Drug court}} is the specific intervention in which a substance-using offender faces court-imposed sanctions such as jail time for missing treatment appointments.',''),
('2014-62','An {{c1::ulnar nerve lesion}} produces weakness and wasting of the {{c2::hypothenar}} muscles with sensory loss over the little and ring fingers.',''),
('2014-63','When a patient holds a fixed delusion, the psychiatrist should {{c1::empathize without directly confronting or challenging}} the delusional belief.',''),
('2014-64','{{c1::Major depressive disorder}} is the leading cause of disability in the U.S. among people aged 15 to 44.',''),
('2014-65','Documenting a thorough {{c1::suicide risk assessment with risk and protective factors}} offers legal protection, whereas no-self-harm contracts do not.',''),
('2014-66','{{c1::Projective identification}} disavows a self/object representation by placing it into another person and inducing them to unconsciously identify with it.',''),
('2014-67','To help a preschooler grieve a departed caregiver, parents should {{c1::show the child pictures}} of the nanny to support healthy mourning.',''),
('2014-68','Charcot-Marie-Tooth type 1A is caused by a {{c1::duplication of the peripheral myelin protein (PMP22) gene}} on chromosome 17.',''),
('2014-69','{{c1::Inhalant (aerosol) abuse}} presents with daytime somnolence, dazed appearance, nausea, and a characteristic {{c2::perioral rash ("glue sniffer''s rash")}}.',''),
('2014-7','With a manipulative, entitled patient, an effective consultant role is {{c1::appealing to the patient''s entitlement}} to redirect it toward desired clinical outcomes.',''),
('2014-70','An acute LSD "bad trip" with severe distress is best treated with a {{c1::benzodiazepine}} such as diazepam, in a calm reassuring setting.',''),
('2014-71','An {{c1::overvalued idea}} is a firmly held, unreasonable belief that is not as fixed as a delusion and is maintained with less than delusional intensity.',''),
('2014-72','Mild waning benefit of clonazepam in panic disorder typically reflects subtherapeutic dosing, so the best step is to {{c1::increase the dose}} rather than assume tolerance or abuse.',''),
('2014-73','Among psychiatric diagnoses, {{c1::alcohol use disorder}} carries the highest risk of interpersonal violence.',''),
('2014-74','Couples therapy is contraindicated when {{c1::motivation is markedly unequal}} between the two partners.',''),
('2014-75','Intimate partner violence is most common among {{c1::low-income families}}.',''),
('2014-76','Progressive apathy, blunted emotion, and loss of initiative point to atrophy of the {{c1::frontal lobe}}, as in frontotemporal dementia.',''),
('2014-77','A core diagnostic feature distinguishing autism spectrum disorder is symptom {{c1::onset before age 3 years}}, not the associated intellectual disability or aggression.',''),
('2014-78','For insomnia disorder, {{c1::cognitive-behavioral therapy (CBT-I)}} yields the best long-term outcomes after treatment ends, superior to hypnotics.',''),
('2014-79','After two failed SSRI trials for panic disorder, an effective next-line option is the tricyclic {{c1::imipramine}}.',''),
('2014-8','Non-REM sleep is characterized by {{c1::decreased recall of dream activity}}, whereas vivid dreaming and autonomic arousal occur in REM.',''),
('2014-80','Serial sevens is a limited test of concentration because successful performance also depends on intact {{c1::arithmetic skills}}.',''),
('2014-81','In Winnicott''s theory, the "good-enough" {{c1::holding environment}} fosters the infant''s spontaneity while protecting the child from harm.',''),
('2014-82','The high suicide rate in epilepsy is most attributable to {{c1::comorbid psychiatric disorders}} such as depression.',''),
('2014-83','In a young woman with new neurologic deficits, multifocal white-matter lesions on brain MRI most suggest {{c1::multiple sclerosis}}.',''),
('2014-84','When ADHD improves but impulsive aggression persists on a stimulant, the next step is to {{c1::optimize (maximize) the stimulant dose}} before adding other agents.',''),
('2014-85','The first step in managing restless legs syndrome is to {{c1::evaluate for iron deficiency}} and check ferritin.',''),
('2014-86','Confusion after starting an SSRI in an elderly patient suggests {{c1::hyponatremia from SIADH}}, best confirmed with {{c2::serum electrolytes}}.',''),
('2014-87','Nortriptyline is the active metabolite of the tricyclic {{c1::amitriptyline}}.',''),
('2014-88','Severe central {{c1::anticholinergic toxicity}} (hot, dry, mydriasis, delirium) from diphenhydramine is treated with {{c2::physostigmine}}.',''),
('2014-89','Feeling {{c1::rested despite very little sleep (decreased need for sleep)}} suggests a manic mood disturbance rather than primary insomnia.',''),
('2014-9','When a patient repeatedly berates staff, the psychiatrist''s first step is to {{c1::set limits}} with the patient.',''),
('2014-90','Following an exposed group and a matched unexposed group forward and comparing outcomes defines a {{c1::cohort study}}.',''),
('2014-91','Regressive, dependent behavior in a hospitalized adolescent is best managed with a {{c1::reward (positive reinforcement)}} system for participating in care.',''),
('2014-92','Idiopathic intracranial hypertension in an obese young woman with papilledema shows {{c1::increased CSF opening pressure}} with otherwise normal fluid and imaging.',''),
('2014-93','In pediatric OCD, comorbid {{c1::tic disorder}} predicts a poorer response to SSRI monotherapy.',''),
('2014-94','A toddler checking the mother''s facial expression before acting is demonstrating {{c1::social referencing}}.',''),
('2014-95','Early HIV-associated (subcortical) dementia features {{c1::decreased processing speed}}, unlike the early cortical deficits (aphasia, apraxia, agnosia) of Alzheimer disease.',''),
('2014-96','DSM-III achieved its breakthrough in diagnostic reliability by standardizing explicit {{c1::diagnostic criteria}}.',''),
('2014-97','Alpha-1 adrenergic antagonism by second-generation antipsychotics causes orthostatic hypotension with reflex {{c1::tachycardia}}.',''),
('2014-98','Adding {{c1::fluoxetine}} can raise clozapine levels (via CYP inhibition) and is used to address persistent cognitive symptoms in clozapine-treated schizophrenia.',''),
('2014-99','Mentalization-based therapy for borderline personality disorder employs {{c1::tactical (judicious) self-disclosure}} by the therapist.',''),
('2015-1','The principle of {{c1::nonmaleficence}} ("first do no harm") obligates clinicians to avoid causing injury to patients.',''),
('2015-10','{{c1::Sedatives}} (benzodiazepines/barbiturates) increase relative {{c2::beta}} frequency on the awake EEG.',''),
('2015-100','Having a patient immediately repeat words like "apple, table, penny" tests {{c1::registration}} (immediate attention/encoding), not delayed recall.',''),
('2015-101','The {{c1::CATIE}} trial showed second-generation antipsychotics were {{c2::no more effective}} than first-generation (perphenazine) for schizophrenia.',''),
('2015-102','Research supports that {{c1::all types}} of early life stress (including emotional neglect) are individual predictors of adult psychiatric disorders.',''),
('2015-103','Paternalism is justified by the ethical principle of {{c1::beneficence}}, acting for the patient''s good potentially against their stated wishes.',''),
('2015-104','{{c1::Botulinum toxin}} injection is the most effective treatment for {{c2::blepharospasm}}.',''),
('2015-105','Incompetence to stand trial is suggested when {{c1::psychotic/delusional}} beliefs impair the defendant''s factual and rational understanding of the proceedings.',''),
('2015-106','In an immunocompromised patient, India ink-positive CSF with encapsulated yeast and elevated opening pressure indicates {{c1::cryptococcal}} meningitis.',''),
('2015-107','Infantile hypotonia, developmental delay, hyperphagia/food foraging, and tantrums characterize {{c1::Prader-Willi syndrome}}.',''),
('2015-108','Asking a patient to tell a story about an ambiguous picture of people is the {{c1::Thematic Apperception Test}}, a projective test.',''),
('2015-109','Explicit sexual behavior knowledge in a young child, such as simulating {{c1::intercourse}}, raises the greatest concern for sexual abuse.',''),
('2015-11','{{c1::DSM-III-R (1987)}} was the first DSM edition to remove homosexuality entirely as a disorder.',''),
('2015-110','{{c1::Light therapy}} (bright light) is first-line, non-pharmacologic treatment for {{c2::seasonal}} pattern major depression.',''),
('2015-111','A {{c1::benzodiazepine}} such as {{c2::lorazepam}} provides the most immediate relief of acute panic attack symptoms, unlike slower-onset SSRIs.',''),
('2015-112','A non-residential father most benefits a child''s mental health by engaging in {{c1::authoritative/traditional parenting}} (homework, holidays), not just recreational companionship.',''),
('2015-113','Postpartum psychosis is most strongly associated with {{c1::bipolar}} disorder.',''),
('2015-114','When a patient becomes physically violent, the safest immediate response is to summon {{c1::law enforcement/security}} to ensure safety.',''),
('2015-115','{{c1::Depression with suicidal ideation}} is a relative contraindication to {{c2::interferon}} therapy, which can induce or worsen depression.',''),
('2015-116','A patient who can describe their diagnosis and treatment plan {{c1::retains capacity}}; difficult behavior alone does not negate it, so the focus shifts to behavior management.',''),
('2015-117','A spontaneous, situation-specific thought like "I''m being left out again" is an {{c1::automatic thought}} in cognitive therapy.',''),
('2015-118','{{c1::Limit setting}} first becomes an especially important parental task during {{c2::toddlerhood}}.',''),
('2015-119','The first manifestation of neurosyphilis is invariably {{c1::meningitis}} (asymptomatic or symptomatic meningeal involvement).',''),
('2015-12','In chronic PTSD with dissociation, hypnosis is best used to help patients gain {{c1::volitional control over dissociation}}, not to retrieve or erase memories.',''),
('2015-120','{{c1::Aripiprazole}} (along with risperidone) has the most evidence for treating irritability and aggression in children with autism spectrum disorder.',''),
('2015-121','Leveraging privileges to promote treatment adherence is {{c1::coercive but ethically acceptable}} when nonadherence would cause significant harm to the patient.',''),
('2015-122','Winnicott''s {{c1::holding environment}} is the safe context provided by {{c2::consistent, reliable parenting}} that supports healthy development.',''),
('2015-123','In {{c1::Broca (nonfluent) aphasia}}, comprehension is preserved, so the patient can follow simple commands but repetition and fluent speech are impaired.',''),
('2015-124','{{c1::Clang associations}} are a disorder of thought {{c2::process}}, whereas obsessions and preoccupations are disorders of thought content.',''),
('2015-125','{{c1::Histrionic}} personality disorder is characterized by rapidly shifting, shallow, and theatrical expression of emotions.',''),
('2015-126','{{c1::Confrontation}} is the therapeutic technique of pointing out a discrepancy a patient is avoiding, such as incongruence between affect and content.',''),
('2015-127','Bilateral {{c1::acoustic neuromas (vestibular schwannomas)}} with café-au-lait spots are characteristic of {{c2::neurofibromatosis type 2}}.',''),
('2015-128','In motivational interviewing, asking {{c1::why a higher rather than lower number}} on a readiness ruler elicits the patient''s own change talk.',''),
('2015-129','{{c1::Illness anxiety disorder}} is preoccupation with having a serious illness despite minimal or absent somatic symptoms and normal evaluation.',''),
('2015-13','Altered mental status with psychosis plus malar rash, proteinuria, pancytopenia, and serositis points to {{c1::lupus cerebritis}}.',''),
('2015-130','{{c1::Syringomyelia}} produces a cape-like loss of pain and temperature with preserved touch plus wasting of the upper limbs.',''),
('2015-131','Routinely {{c1::collecting patient feedback}} about the treatment most improves psychotherapy outcomes across modalities.',''),
('2015-132','In split treatment the prescribing psychiatrist {{c1::retains full responsibility}} for the patient''s overall care.',''),
('2015-133','After a myocardial infarction, an {{c1::SSRI such as sertraline}} is the preferred antidepressant because of its cardiac safety.',''),
('2015-134','Preventing vomiting until post-meal distress fades reduces the behavior through {{c1::extinction}}, by removing its anxiety-relieving reinforcement.',''),
('2015-135','A patient with a near-lethal, concealed suicide attempt and ongoing ambivalence about surviving requires {{c1::inpatient hospitalization}}.',''),
('2015-136','{{c1::Serotonin syndrome}}, with clonus, hyperreflexia, and autonomic instability, is treated with the antagonist {{c2::cyproheptadine}}.',''),
('2015-137','A behavior repeated because it produces a mood-lifting reward is maintained by {{c1::operant conditioning}} (positive reinforcement).',''),
('2015-138','Chronic traumatic encephalopathy is a {{c1::tauopathy}}, with hyperphosphorylated tau deposited around small vessels in cortical sulci.',''),
('2015-139','Avoiding food due to a circumscribed fear of choking (without weight/body concerns) is best diagnosed as a {{c1::specific phobia}}.',''),
('2015-14','False belief of pregnancy with physical pregnancy signs but negative tests and ultrasound defines {{c1::pseudocyesis}}.',''),
('2015-140','A waddling gait with pelvic drop and trunk lean (Trendelenburg) reflects proximal weakness seen in {{c1::muscular dystrophy}}.',''),
('2015-141','Rapidly progressive dementia with myoclonus suggests Creutzfeldt-Jakob disease, with {{c1::spongiform (microvacuolar) change}} on autopsy.',''),
('2015-142','When abuse is suspected, the suspected abuser (and any relative interpreter) must be {{c1::excluded}}; use a {{c2::neutral professional interpreter}} instead.',''),
('2015-143','Reliably distinguishing pretend from reality marks the transition from the {{c1::preoperational}} to the {{c2::concrete operational}} stage.',''),
('2015-144','Because of faster hepatic metabolism, prepubertal children often need {{c1::higher weight-adjusted doses}} of liver-metabolized medications.',''),
('2015-145','{{c1::Spasticity}} is velocity-dependent, favors antigravity muscles, and is accompanied by hyperreflexia, reflecting upper motor neuron lesions.',''),
('2015-146','Asking what a patient would do in a hypothetical situation tests {{c1::judgment}}.',''),
('2015-147','The 1972 {{c1::Feighner criteria}} shifted U.S. psychiatry by introducing {{c2::operationalized diagnostic criteria}}, laying groundwork for DSM-III.',''),
('2015-148','In split treatment the psychiatrist evaluates and prescribes medication while maintaining {{c1::regular contact with the therapist}}.',''),
('2015-149','Rapid correction of severe hyponatremia causes {{c1::central pontine myelinolysis}}, presenting with quadriparesis, dysarthria, and dysphagia.',''),
('2015-15','A {{c1::clear sensorium}} (intact orientation) distinguishes alcoholic hallucinosis from delirium tremens, which causes clouded consciousness.',''),
('2015-150','In DSM-5, ataque de nervios most often maps onto an {{c1::anxiety disorder}}.',''),
('2015-151','{{c1::Lorazepam}} is reliably absorbed by both oral and {{c2::intramuscular}} routes, unlike diazepam and chlordiazepoxide.',''),
('2015-152','Bilateral parotid (sialadenosis) enlargement in an eating disorder is a sign of repeated {{c1::self-induced vomiting}}.',''),
('2015-153','In OCD exposure and response prevention, anxiety to the feared stimulus declines through {{c1::habituation}}.',''),
('2015-154','A child who fails to seek comfort and shows minimal positive affect after disrupted caregiving has {{c1::reactive attachment disorder}}.',''),
('2015-155','The triad of dementia, urinary incontinence, and gait apraxia with enlarged ventricles indicates {{c1::normal pressure hydrocephalus}}.',''),
('2015-156','In normal aging, {{c1::word knowledge (verbal/crystallized ability)}} is the last cognitive domain to decline.',''),
('2015-157','DSM-5 requires ADHD symptoms to be present before age {{c1::12}}.',''),
('2015-158','A patient''s social-media friend request should be handled by {{c1::discussing the boundaries}} of the therapeutic relationship, not by accepting it.',''),
('2015-159','Inhalant-induced psychosis is self-limited and managed with {{c1::watchful waiting}} in a calm, supportive setting.',''),
('2015-16','Persistent distress from incongruence between experienced and assigned gender defines {{c1::gender dysphoria}}.',''),
('2015-160','{{c1::Antidepressants}} are a recognized secondary (medication) cause of restless legs syndrome.',''),
('2015-161','The NIMH was founded amid optimism from successful psychiatric {{c1::treatment of soldiers in World War II}}.',''),
('2015-162','In a clozapine patient with eosinophilia, tachycardia, and dyspnea, suspect {{c1::myocarditis}} and check a {{c2::troponin}} level.',''),
('2015-163','Hypnosis has its strongest evidence base among GI disorders for treating {{c1::irritable bowel syndrome}}.',''),
('2015-164','DSM-5 requires sleep difficulty for at least {{c1::3 months}} (three nights/week) to diagnose insomnia disorder.',''),
('2015-165','For acute traumatic stress, the best early intervention is {{c1::normalizing the stress reaction and mobilizing social supports}}, not debriefing or routine medication.',''),
('2015-166','Difficulty discarding possessions due to perceived value, causing clutter that impairs living space, defines {{c1::hoarding disorder}}.',''),
('2015-167','Once delirium improves, antipsychotics like haloperidol should be {{c1::discontinued}} rather than continued for residual disorientation.',''),
('2015-168','Genito-pelvic pain/penetration disorder is best treated with graded {{c1::vaginal dilators}} (dilation therapy).',''),
('2015-169','Schizophrenia that persists after adequate trials of two antipsychotics is treatment-resistant and warrants {{c1::clozapine}}.',''),
('2015-17','{{c1::Sensate focus}} is a sex-therapy technique where partners explore each other''s bodies while initially avoiding breasts and genitals.',''),
('2015-170','Vygotsky''s {{c1::zone of proximal development}} is the range of tasks a child can master with appropriate guidance.',''),
('2015-171','Cigarette smoking induces CYP1A2, increasing metabolism and lowering levels of {{c1::clozapine}}.',''),
('2015-172','{{c1::Sertraline}} can cause a false-positive urine immunoassay screen for {{c2::benzodiazepines}}.',''),
('2015-173','Holding a {{c1::group meeting of all members}} maximizes voluntary contributions by reducing social loafing and the bystander effect.',''),
('2015-174','Carbon monoxide poisoning characteristically produces bilateral necrosis of the {{c1::globus pallidus}}.',''),
('2015-175','A key advantage of TMS over ECT is that it requires {{c1::no anesthesia}} and causes no seizure or cognitive side effects.',''),
('2015-176','Sudden, isolated anterograde amnesia with repetitive questioning and otherwise intact cognition defines {{c1::transient global amnesia}}.',''),
('2015-177','Schneider''s first-rank symptoms of schizophrenia include {{c1::voices arguing or commenting}} on the patient.',''),
('2015-178','As ADHD persists into adulthood, overt {{c1::hyperactivity}} typically diminishes while inattention and impulsivity remain.',''),
('2015-179','Methadone doses of about {{c1::80-120 mg/day}} are generally needed to suppress drug hunger and produce cross-tolerance blockade.',''),
('2015-18','New-onset psychosis at age 75 with normal cognition, exam, and MRI is best diagnosed as {{c1::schizophrenia}} (very-late-onset), not a neurodegenerative dementia.',''),
('2015-180','Academic impairment in a child with a chronic tic disorder is most often caused by comorbid {{c1::ADHD}}.',''),
('2015-181','Serial sevens on the mental status exam is primarily a test of {{c1::concentration}} (attention), not memory or orientation.',''),
('2015-182','{{c1::Complex partial}} seizures cause impaired awareness with {{c2::automatisms}} (lip-smacking, picking) followed by postictal confusion and amnesia for the event.',''),
('2015-183','Among tricyclics, {{c1::imipramine}} plasma level shows a defined correlation with antidepressant therapeutic response.',''),
('2015-184','Chronic severe irritability with frequent outbursts in childhood (DMDD-like) most often progresses to {{c1::anxiety}} and unipolar depressive disorders, not bipolar, in adulthood.',''),
('2015-185','First same-sex attraction in gay men typically emerges around {{c1::early adolescence}} (roughly age 10–12), preceding self-identification as gay.',''),
('2015-186','Failing to obtain informed consent violates the ethical principle of {{c1::autonomy}}, the patient''s right to self-determination.',''),
('2015-187','In locked-in syndrome from {{c2::basilar artery}} occlusion (ventral pons), patients retain only {{c1::vertical eye movements and blinking}}.',''),
('2015-188','In elderly depressed patients needing a TCA, {{c1::desipramine}} (a secondary amine) is preferred for its low anticholinergic and orthostatic side effects.',''),
('2015-189','{{c1::Purging behavior}} causes {{c2::hypokalemia}}, producing flattened T-waves and U-waves on EKG.','')
insert into flashcards (question_id, cloze_text, extra) values
('2015-19','A history of {{c1::multiple major depressive episodes}} is the key indicator for maintenance antidepressant therapy after recovery.',''),
('2015-190','Decreased attention to social cues (impaired joint attention) is most characteristic of {{c1::autism spectrum disorder}}.',''),
('2015-191','The {{c1::clock drawing}} test best distinguishes executive dysfunction from depression in apathetic elderly patients.',''),
