('2016-279','Neural plasticity is mediated largely by rapid changes in the number and morphology of {{c1::dendritic spines}}.','')
insert into flashcards (question_id, cloze_text, extra) values
('2016-28','Global mental health differs most from other global medicine in that {{c1::cultural beliefs}} more strongly shape how disorders are understood and diagnosed.',''),
