insert into flashcards (question_id, cloze_text, extra) values
('2020-281','A principal contributor to object relations theory was {{c1::Melanie Klein}}.',''),
('2020-282','Odd beliefs (auras, magical thinking), social isolation, and lifelong eccentricity suggest {{c1::schizotypal}} personality disorder.',''),
('2020-283','Puberty begins with pulsatile GnRH secretion from neurons in the {{c1::infundibular (arcuate)}} nucleus of the hypothalamus.',''),
('2020-284','When medication serves as a transitional object, it provides a sense of {{c1::connectedness to the physician}} between infrequent visits.',''),
('2020-285','Distressing incongruence between experienced gender and assigned birth gender is termed {{c1::gender dysphoria}}.',''),
('2020-286','The triple screen for Down syndrome measures AFP, estriol, and {{c1::human chorionic gonadotropin (hCG)}}.',''),
('2020-287','The factor most associated with men who assault intimate partners is a {{c1::history of childhood abuse}}.',''),
('2020-288','Differential gene expression based on whether the allele was inherited from the mother or father is called genomic {{c1::imprinting}}.',''),
('2020-289','The comorbidity most frequently associated with autism spectrum disorder is {{c1::intellectual disability}}.',''),
